    bestDiscount = Math.max(bestDiscount, d);
  }

  // coffee-multibuy-3: qty >= 3 and category === 'coffee' -> 5% off
  if (p.category === 'coffee' && l.qty >= 3) {
    const d = Math.round(p.priceCents * l.qty * 5) / 100;
    bestDiscount = Math.max(bestDiscount, d);
